// Fecha de hoy y el límite de la ventana que vamos a consultar (8 días).
// Todo en la zona horaria del local para no desfasar el día.
const tz = 'America/Argentina/Buenos_Aires';
const fmt = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' });
const hoy = new Date();
const limite = new Date(hoy.getTime() + 8 * 86400000);
return [{ json: { hoy: fmt.format(hoy), limite: fmt.format(limite) } }];

// Misma lógica que la pestaña "Habituales" del panel (docs/js/admin.js),
// pero acá decide a quién hay que escribirle HOY por WhatsApp:
// el que le toca en exactamente 2 días, sin turno todavía y sin conflicto.
const DIAS_AVISO = 2;

const habituales = $('Traer habituales').all().map(i => i.json);
const horarios   = $('Traer horarios').all().map(i => i.json);
const bloqueos   = $('Traer bloqueos').all().map(i => i.json);
const turnos     = $('Traer turnos').all().map(i => i.json);

const DIAS = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];

function isoDeFecha(d) {
  return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
}
function proximaFecha(diaSemana, pausadoHasta) {
  const f = new Date(); f.setHours(0,0,0,0);
  for (let i = 0; i < 21; i++) {
    if (f.getDay() === diaSemana) {
      const iso = isoDeFecha(f);
      if (!pausadoHasta || iso > pausadoHasta) return iso;
    }
    f.setDate(f.getDate() + 1);
  }
  return null;
}

const hoy = new Date(); hoy.setHours(0,0,0,0);
const candidatos = [];

for (const row of habituales) {
  const fecha = proximaFecha(row.dia_semana, row.pausado_hasta);
  if (!fecha) continue;

  const objetivo = new Date(hoy.getTime() + DIAS_AVISO * 86400000);
  if (fecha !== isoDeFecha(objetivo)) continue; // no es el día de avisarle todavía

  const dur = (row.servicios && row.servicios.duracion_min) || 30;
  const inicio = new Date(`${fecha}T${row.hora}:00`);
  const fin = new Date(inicio.getTime() + dur * 60000);

  const yaConfirmado = turnos.some(t =>
    t.barbero_id === row.barbero_id &&
    t.cliente_telefono === row.cliente_telefono &&
    t.inicio.slice(0, 10) === fecha);
  if (yaConfirmado) continue;

  const horarioActivo = horarios.some(h =>
    h.barbero_id === row.barbero_id && h.dia_semana === row.dia_semana && h.activo &&
    row.hora >= h.hora_inicio.slice(0,5) && row.hora < h.hora_fin.slice(0,5));
  const bloqueado = bloqueos.some(b =>
    (b.barbero_id === row.barbero_id || !b.barbero_id) &&
    new Date(b.inicio) < fin && new Date(b.fin) > inicio);
  if (!horarioActivo || bloqueado) continue; // conflicto: el panel ya se lo avisa al barbero, no le escribimos al cliente

  candidatos.push({
    json: {
      barbero_id: row.barbero_id,
      servicio_id: row.servicio_id,
      barbero: row.barberos ? row.barberos.nombre : '',
      servicio: row.servicios ? row.servicios.nombre : '',
      cliente_nombre: row.cliente_nombre,
      cliente_telefono: row.cliente_telefono.replace(/\D/g, ''),
      dia: DIAS[row.dia_semana],
      hora: row.hora,
      fecha,
      inicio_iso: inicio.toISOString()
    }
  });
}
return candidatos;

